sp_widget.script:
(function() {
  data.sections = [];
  data.applicationId = $sp.getParameter("app_id") || "";
  data.applicationName = "";

  try {
    if (!data.applicationId) return;

    var appGr = new GlideRecord("x_1433041_identi_0_application");
    if (appGr.get(data.applicationId)) {
      data.applicationName = appGr.getValue("name");
    }

    // Get responses grouped by section
    var respGr = new GlideRecord("x_1433041_identi_0_response");
    respGr.addQuery("application", data.applicationId);
    respGr.orderBy("section");
    respGr.setLimit(200);
    respGr.query();

    var sectionMap = {};
    while (respGr.next()) {
      var sectionId = respGr.getValue("section");
      if (!sectionMap[sectionId]) {
        sectionMap[sectionId] = { name: respGr.getDisplayValue("section"), answered: 0, total: 0 };
      }
      sectionMap[sectionId].total++;
      if (respGr.getValue("value") && respGr.getValue("value") !== "") {
        sectionMap[sectionId].answered++;
      }
    }

    for (var key in sectionMap) {
      var s = sectionMap[key];
      s.sys_id = key;
      s.complete = s.answered === s.total;
      data.sections.push(s);
    }
  } catch (e) {
    gs.error("IBAR Review Summary widget error: " + e.message);
  }
})();
